var r={en:`Catalog, Orders and Inventory deploy separately but share schemas and demand coordinated releases by one team.`,ua:`Catalog, Orders та Inventory розгортаються окремо, але ділять схеми й потребують синхронних релізів однією командою.`};var n={en:[`Map release and data coupling in the current diagram.`,`Compare keeping services, merging modules or redrawing boundaries.`,`Write an ADR with an incremental reversible experiment.`],ua:[`Познач залежності релізів і даних у схемі.`,`Порівняй збереження сервісів, об’єднання модулів і перегляд меж.`,`Напиши ADR з поступовим зворотним експериментом.`]};var s=[{en:`Each mutable dataset has a declared owner.`,ua:`Кожен змінюваний набір даних має власника.`},{en:`Proposed cross-boundary contracts can evolve compatibly.`,ua:`Контракти між межами можуть еволюціонувати сумісно.`}];var o={scenario:r,tasks:n,checks:s};export{s as checks,o as default,r as scenario,n as tasks};